1	package models
2	
3	import (
4		"errors"
5		"fmt"
6	)
7	
8	const maxTenantLen = 32
9	
10	// Tenant identifies the owner of a device fleet. A Tenant can only be
11	// obtained through ParseTenant, so every value in circulation is already
12	// non-empty, lowercase, and at most 32 characters long; nothing downstream
13	// needs to check it again.
14	type Tenant struct {
15		id string
16	}
17	
18	// ParseTenant validates a raw tenant identifier once, at the boundary.
19	func ParseTenant(raw string) (Tenant, error) {
20		if raw == "" {
21			return Tenant{}, errors.New("tenant: empty")
22		}
23		if len(raw) > maxTenantLen {
24			return Tenant{}, fmt.Errorf("tenant %q: longer than %d characters", raw, maxTenantLen)
25		}
26		for _, r := range raw {
27			if !isTenantRune(r) {
28				return Tenant{}, fmt.Errorf("tenant %q: want lowercase letters, digits, or '-'", raw)
29			}
30		}
31		return Tenant{id: raw}, nil
32	}
33	
34	// ID returns the validated identifier for use in storage keys and logs.
35	func (t Tenant) ID() string {
36		return t.id
37	}
38	
39	func isTenantRune(r rune) bool {
40		return (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '-'
41	}
42

1	package models
2	
3	import (
4		"slices"
5		"strings"
6	)
7	
8	func NormalizeTags(tags []string) []string {
9		var out []string
10		for _, t := range tags {
11			t = strings.TrimSpace(t)
12			if t == "" || slices.Contains(out, t) {
13				continue
14			}
15			if strings.HasPrefix(t, "region:") && !isRegionCode(t[7:]) {
16				continue
17			}
18			out = append(out, t)
19		}
20		return out
21	}
22	
23	func isRegionCode(code string) bool {
24		return code == "eu" || code == "us" || code == "ap"
25	}
26

1	package models
2	
3	import (
4		"errors"
5		"fmt"
6		"slices"
7		"time"
8	)
9	
10	// Weekday is a weekday.
11	type Weekday = time.Weekday
12	
13	// Schedule is a schedule.
14	type Schedule struct {
15		days []Weekday
16	}
17	
18	// NewSchedule creates a new Schedule.
19	func NewSchedule(days []Weekday) (Schedule, error) {
20		if len(days) == 0 {
21			return Schedule{}, errors.New("schedule: no days")
22		}
23		for _, d := range days {
24			if d < time.Sunday || d > time.Saturday {
25				return Schedule{}, fmt.Errorf("schedule: bad weekday %d", d)
26			}
27		}
28		return Schedule{days: days}, nil
29	}
30	
31	// Days returns the days.
32	func (s Schedule) Days() []Weekday {
33		return s.days
34	}
35	
36	// Includes returns whether the schedule includes the day.
37	func (s Schedule) Includes(d Weekday) bool {
38		return slices.Contains(s.days, d)
39	}
40

1	package models
2	
3	import "fmt"
4	
5	// ParsePriority accepts the integer devices send on the wire and rejects
6	// anything outside the range the scheduler knows how to order.
7	func ParsePriority(n int) (Priority, error) {
8		if n < int(Low) || n > int(High) {
9			return 0, fmt.Errorf("priority %d: want %d-%d", n, Low, High)
10		}
11		return Priority(n), nil
12	}
13	
14	// Outranks reports whether p should be scheduled ahead of o.
15	func (p Priority) Outranks(o Priority) bool {
16		return p > o
17	}
