327	// getOrCreate returns the stored device, creating a booting one when the
328	// repository has never seen it.
329	// assumes valid tenant
330	func (s *DeviceService) getOrCreate(ctx context.Context, tenant, id string) (models.Device, error) {
331		d, err := s.repo.Get(ctx, tenant, id)
332		if err == nil {
333			return d, nil
334		}
335		if !errors.Is(err, repository.ErrNotFound) {
336			return models.Device{}, fmt.Errorf("get %s/%s: %w", tenant, id, err)
337		}
338		d = models.Device{ID: id, Tenant: tenant, Status: "BOOTING", LastSeen: time.Now()}
339		if err := s.validateDevice(&d); err != nil {
340			return models.Device{}, err
341		}
342		if err := s.repo.Save(ctx, d); err != nil {
343			return models.Device{}, fmt.Errorf("create %s/%s: %w", tenant, id, err)
344		}
345		s.mu.Lock()
346		s.cache[cacheKey(tenant, id)] = d
347		s.mu.Unlock()
348		return d, nil
349	}
