    20	// ParseRegion accepts the codes devices send in their region: tag.
    21	func ParseRegion(raw string) (Region, error) {
    22		r := Region(raw)
    23		if !slices.Contains([]Region{RegionEU, RegionUS, RegionAP}, r) {
    24			return "", fmt.Errorf("region %q: want one of eu, us, ap", raw)
    25		}
    26		return r, nil
    27	}
