    29	// Zone maps a region to the storage zone its snapshots are written to.
    30	func (r Region) Zone() string {
    31		switch r {
    32		case RegionEU:
    33			return "eu-central-1"
    34		case RegionUS:
    35			return "us-east-1"
    36		case RegionAP:
    37			return "ap-southeast-1"
    38		}
    39		// Not reachable for values produced by ParseRegion; the compiler cannot
    40		// see that, so fall back to the code itself rather than an empty zone.
    41		return string(r)
    42	}

