474	// Retry re-sends the down notification for a device.
475	func (s *DeviceService) Retry(ctx context.Context, tenant, id string) error {
476		d, err := s.Get(ctx, tenant, id)
477		if err != nil {
478			return err
479		}
480		if d.Status != models.StatusDown {
481			return nil
482		}
483		s.mu.Lock()
484		s.retries++
485		s.mu.Unlock()
486		return withRetry(3, func() error {
487			return s.notifier.Send("ops", "device "+id+" is still down")
488		})
489	}
