22	// Heartbeat returns the heartbeat handler. The body is one raw heartbeat
23	// line, the tenant comes from the X-Tenant header and ?force=1 forces the
24	// reported status through.
25	func Heartbeat(svc *services.DeviceService) http.HandlerFunc {
26		return func(w http.ResponseWriter, r *http.Request) {
27			raw, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxHeartbeatBytes))
28			if err != nil {
29				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "unreadable body"})
30				return
31			}
32			tenant := r.Header.Get("X-Tenant")
33			if tenant == "" {
