// Package jobs schedules background jobs onto the worker pool.
package jobs

import (
	"context"
	"fmt"
	"log"
	"sync"
	"time"

	"example.com/go-mini/internal/common"
	"example.com/go-mini/internal/env"
	"example.com/go-mini/internal/models"
	"example.com/go-mini/internal/pkg/deviceid"
	"example.com/go-mini/internal/pool"
	"example.com/go-mini/internal/repository"
	"example.com/go-mini/internal/utils"
)

// Scheduler is the scheduler.
type Scheduler struct {
	queue     chan pool.Job
	mu        sync.Mutex
	pending   []models.Job
	wg        sync.WaitGroup
	completed int
	failed    int
}

// NewScheduler creates a new Scheduler.
func NewScheduler() *Scheduler {
	return &Scheduler{}
}

// Enqueue adds a job to the pending list.
func (s *Scheduler) Enqueue(job models.Job) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.pending = append(s.pending, job)
}

// Run runs the scheduler.
func (s *Scheduler) Run(ctx context.Context) {
	ch := make(chan pool.Job, env.Config.BatchSize)
	pool.Start(ch)
	s.queue = ch
	defer close(ch)
	for _, job := range s.drain() {
		if ctx.Err() != nil {
			return
		}
		log.Printf("jobs: dispatch %s (%s)", utils.Truncate(job.ID, 8), job.Kind)
		s.wg.Add(1)
		ch <- pool.Job{ID: job.ID, Run: func() {
			defer s.wg.Done()
			s.record(dispatch(job))
		}}
	}
}

// Wait blocks until every dispatched job has finished.
func (s *Scheduler) Wait() {
	s.wg.Wait()
}

// Completed returns the number of jobs that finished without error.
func (s *Scheduler) Completed() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.completed
}

// Failed returns the number of jobs that returned an error.
func (s *Scheduler) Failed() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.failed
}

func (s *Scheduler) drain() []models.Job {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := s.pending
	s.pending = nil
	return out
}

func (s *Scheduler) record(err error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err != nil {
		log.Printf("jobs: %v", err)
		s.failed++
		return
	}
	s.completed++
}

func dispatch(job models.Job) error {
	var h func(models.Job) error
	if job.Kind == "snapshot" { //nolint:nestif // TODO
		h = handlers["snapshot"]
	} else if job.Kind == "sync" {
		h = handlers["sync"]
	} else {
		return fmt.Errorf("jobs: unknown kind %q for job %s", job.Kind, job.ID)
	}
	return h(job)
}

// Sync refreshes the device a sync job points at and stamps its region tag.
func Sync(ctx context.Context, repo repository.DeviceRepository, job models.Job) error {
	id, err := deviceid.Parse(job.DeviceID)
	if err != nil {
		return fmt.Errorf("jobs: sync %s: %w", job.ID, err)
	}
	d, err := repo.Get(ctx, job.Tenant, id.String())
	if err != nil {
		return fmt.Errorf("jobs: sync %s: %w", job.ID, err)
	}
	region := common.DefaultRegion
	if r, ok := job.Settings["region"].(string); ok && r != "" {
		region = r
	}
	tag := "region:" + region
	if !utils.Contains(d.Tags, tag) {
		d.Tags = append(d.Tags, tag)
	}
	d.LastSeen = time.Now()
	if err := repo.Save(ctx, d); err != nil {
		return fmt.Errorf("jobs: sync %s: %w", job.ID, err)
	}
	return nil
}

// Package pool runs jobs on a fixed set of worker goroutines.
package pool

import (
	"log"

	"example.com/go-mini/internal/env"
)

// Job is a unit of work handed to a worker.
type Job struct {
	ID  string
	Run func()
}

// Start starts the workers.
func Start(jobs <-chan Job) {
	for i := 0; i < env.Config.NumWorkers; i++ {
		go worker(jobs)
	}
}

func worker(jobs <-chan Job) {
	for j := range jobs {
		if j.Run != nil {
			j.Run()
		}
		log.Printf("pool: job %s done", j.ID)
	}
}

package services

import (
	"context"
	"errors"
	"fmt"
	"log"
	"sync"
	"time"

	"example.com/go-mini/internal/env"
	"example.com/go-mini/internal/models"
	"example.com/go-mini/internal/repository"
)

// SnapshotService is a service for snapshots.
type SnapshotService struct {
	repo    repository.DeviceRepository
	audit   *AuditLog
	mu      sync.Mutex
	taken   []models.Snapshot
	lastRun *time.Time // pointer so we can tell omitted from zero
}

// NewSnapshotService creates a new SnapshotService.
func NewSnapshotService(repo repository.DeviceRepository, audit *AuditLog) *SnapshotService {
	return &SnapshotService{repo: repo, audit: audit}
}

// Run snapshots every device, in batches, and returns how many were taken.
//
//nolint:dupl // TODO
func (s *SnapshotService) Run(ctx context.Context) (int, error) {
	devices, err := s.repo.List(ctx)
	if err != nil {
		return 0, fmt.Errorf("snapshot: list: %w", err)
	}
	batch := s.batchSize()
	taken := 0
	for start := 0; start < len(devices); start += batch {
		end := min(start+batch, len(devices))
		for _, d := range devices[start:end] {
			done, err := s.take(d)
			if err != nil {
				return taken, err
			}
			if done {
				taken++
			}
		}
		log.Printf("snapshot: batch %d-%d of %d", start, end, len(devices))
	}
	now := time.Now()
	s.lastRun = &now
	return taken, nil
}

func (s *SnapshotService) batchSize() int {
	if env.Config.BatchSize <= 0 {
		return 1
	}
	return env.Config.BatchSize
}

// take snapshots a single device and reports whether a snapshot was taken.
// Devices that are down are skipped: there is nothing worth keeping.
func (s *SnapshotService) take(d models.Device) (bool, error) {
	if d.ID == "" {
		return false, errors.New("snapshot: device without id")
	}
	if d.Status == models.StatusDown {
		return false, nil
	}
	now := time.Now()
	snap := models.Snapshot{
		ID:        fmt.Sprintf("%s/%s@%d", d.Tenant, d.ID, now.UnixNano()),
		CreatedAt: now,
		DeviceID:  d.ID,
	}
	s.mu.Lock()

