11	// MemStore keeps the fleet in memory. It is the store behind `svc --dry-run`,
12	// where an operator replays recorded heartbeats without writing anything to
13	// disk.
14	type MemStore struct {
15		mu      sync.Mutex
16		devices map[string]models.Device
17	}
18	
19	// NewMemStore creates a new MemStore.
20	func NewMemStore() *MemStore {
21		return &MemStore{devices: map[string]models.Device{}}
22	}
23	
24	// Get gets a device.
25	func (m *MemStore) Get(ctx context.Context, tenant, id string) (models.Device, error) {
26		if err := ctx.Err(); err != nil {
27			return models.Device{}, fmt.Errorf("mem store: get: %w", err)
28		}
29		m.mu.Lock()
30		defer m.mu.Unlock()
31		d, ok := m.devices[key(tenant, id)]
