11	// Cache is a cache of devices.
12	type Cache struct {
13		mu    sync.Mutex
14		items map[string]models.Device
15		ttl   map[string]time.Time
16		span  time.Duration
17	}
18	
19	// NewCache creates a new Cache whose entries expire after span.
20	func NewCache(span time.Duration) *Cache {
21		return &Cache{
22			items: map[string]models.Device{},
23			ttl:   map[string]time.Time{},
24			span:  span,
25		}
26	}
27	
28	func (c *Cache) Put(d models.Device) {
29		key := cacheKey(d.Tenant, d.ID)
30		c.mu.Lock()
31		c.items[key] = d
32		c.mu.Unlock()
33		c.ttl[key] = time.Now().Add(c.span)
34	}
35	
36	// Get returns the cached device and refreshes its expiry. Entries that have
37	// expired are dropped on the way.
38	func (c *Cache) Get(key string) (models.Device, bool) {
39		c.mu.Lock()
40		defer c.mu.Unlock()
41		now := time.Now()
42		for k, exp := range c.ttl {
43			if exp.Before(now) {
44				delete(c.items, k)
45				delete(c.ttl, k)
46			}
47		}
48		d, ok := c.items[key]
49		if ok {
50			c.ttl[key] = now.Add(c.span)
51		}
52		return d, ok
53	}
54	
55	// All returns every cached device.
56	func (c *Cache) All() map[string]models.Device {
57		return c.items
58	}
59	
60	// Len returns the number of cached devices.
61	func (c *Cache) Len() int {
62		c.mu.Lock()
63		defer c.mu.Unlock()
64		return len(c.items)
65	}
66	
67	// Footprint estimates the memory the cache holds, in bytes.
68	func (c *Cache) Footprint() int {
69		c.mu.Lock()
70		defer c.mu.Unlock()
71		items := c.items
72		size := len(items)
73		for _, d := range items {
74			size += len(d.ID) + len(d.Tenant) + len(d.Version)
75		}
76		size = size * 10 // rough per-entry overhead
77		size += len(c.ttl) * 24
78		return size
79	}
80	
81	// String renders the cache for logs.
82	func (c *Cache) String() string {
83		return describe(*c) //nolint:govet // TODO
84	}
85	
86	func describe(c Cache) string { //nolint:govet // TODO
87		return fmt.Sprintf("cache: %d items, %d expiring", len(c.items), len(c.ttl))
88	}
