16	// SnapshotService is a service for snapshots.
17	type SnapshotService struct {
18		repo    repository.DeviceRepository
19		audit   *AuditLog
20		mu      sync.Mutex
21		taken   []models.Snapshot
22		lastRun *time.Time // pointer so we can tell omitted from zero
23	}
24	
25	// NewSnapshotService creates a new SnapshotService.
26	func NewSnapshotService(repo repository.DeviceRepository, audit *AuditLog) *SnapshotService {
27		return &SnapshotService{repo: repo, audit: audit}
28	}
29	
30	// Run snapshots every device, in batches, and returns how many were taken.
31	//
32	//nolint:dupl // TODO
33	func (s *SnapshotService) Run(ctx context.Context) (int, error) {
34		devices, err := s.repo.List(ctx)
35		if err != nil {
36			return 0, fmt.Errorf("snapshot: list: %w", err)
37		}
38		batch := s.batchSize()
39		taken := 0
40		for start := 0; start < len(devices); start += batch {
41			end := min(start+batch, len(devices))
42			for _, d := range devices[start:end] {
43				done, err := s.take(d)
44				if err != nil {
45					return taken, err
46				}
47				if done {
48					taken++
49				}
50			}
51			log.Printf("snapshot: batch %d-%d of %d", start, end, len(devices))
52		}
53		now := time.Now()
54		s.lastRun = &now
55		return taken, nil
56	}
57	
58	func (s *SnapshotService) batchSize() int {
59		if env.Config.BatchSize <= 0 {
60			return 1
61		}
62		return env.Config.BatchSize
63	}
64	
65	// take snapshots a single device and reports whether a snapshot was taken.
66	// Devices that are down are skipped: there is nothing worth keeping.
67	func (s *SnapshotService) take(d models.Device) (bool, error) {
68		if d.ID == "" {
69			return false, errors.New("snapshot: device without id")
70		}
71		if d.Status == models.StatusDown {
72			return false, nil
73		}
74		now := time.Now()
75		snap := models.Snapshot{
76			ID:        fmt.Sprintf("%s/%s@%d", d.Tenant, d.ID, now.UnixNano()),
77			CreatedAt: now,
78			DeviceID:  d.ID,
79		}
80		s.mu.Lock()
81		s.taken = append(s.taken, snap)
82		s.mu.Unlock()
83		_ = s.audit.Write("snapshot " + snap.ID)
84		return true, nil
85	}
86	
87	// Taken returns the snapshots taken so far.
88	func (s *SnapshotService) Taken() []models.Snapshot {
89		s.mu.Lock()
90		defer s.mu.Unlock()
91		return s.taken
92	}
93	
94	// Handle runs the job if it is a snapshot job.
95	func (s *SnapshotService) Handle(ctx context.Context, job models.Job) error {
96		if job.Kind == "snapshot" {
97			_, err := s.Run(ctx)
98			return err
99		}
100		if job.Kind == "sync" {
101			return nil // sync jobs are handled by the sync service
102		}
103		return fmt.Errorf("snapshot: unknown job kind %q", job.Kind)
104	}
105	
106	// Manifest describes the snapshots taken so far.
107	func (s *SnapshotService) Manifest() map[string]interface{} {
108		s.mu.Lock()
109		defer s.mu.Unlock()
110		contentType := "application/json" //nolint:goconst // TODO
111		return map[string]interface{}{
112			"count":        len(s.taken),
113			"content_type": contentType,
114			"snapshots":    s.taken,
115		}
116	}
