91	// NewDeviceService creates a new DeviceService.
92	//
93	// The notifier and the audit log may be nil; both degrade to no-ops.
94	func NewDeviceService(repo repository.DeviceRepository, notifier *Notifier, audit *AuditLog) *DeviceService {
95		s := &DeviceService{
96			repo:     repo,
97			notifier: notifier,
98			audit:    audit,
99			cache:    map[string]models.Device{},
100			lastSeen: map[string]time.Time{},
101			started:  time.Now(),
102		}
103		go s.flushLoop()
104		return s
