14	// SyncService is a service for syncing.
15	type SyncService struct {
16		repo     repository.DeviceRepository
17		notifier *Notifier
18		region   string
19		batch    int
20		retries  int
21		dryRun   bool
22		lastRun  *time.Time // pointer so we can tell omitted from zero
23	}
24	
25	// NewSyncService creates a new SyncService.
26	func NewSyncService(repo repository.DeviceRepository, notifier *Notifier, region string, batch int, retries int, dryRun bool) *SyncService { //nolint:revive // TODO
27		return &SyncService{
28			repo:     repo,
29			notifier: notifier,
30			region:   region,
31			batch:    batch,
32			retries:  retries,
33			dryRun:   dryRun,
34		}
35	}
36	
37	// Run syncs every device in the region, in batches, and returns how many
38	// were synced.
39	//
40	//nolint:dupl // TODO
41	func (s *SyncService) Run(ctx context.Context) (int, error) {
42		devices, err := s.repo.List(ctx)
43		if err != nil {
44			return 0, fmt.Errorf("sync: list: %w", err)
45		}
46		batch := s.batchSize()
47		synced := 0
48		for start := 0; start < len(devices); start += batch {
49			end := min(start+batch, len(devices))
50			for _, d := range devices[start:end] {
51				done, err := s.syncOne(d)
52				if err != nil {
53					return synced, err
54				}
55				if done {
56					synced++
57				}
58			}
59			log.Printf("sync: batch %d-%d of %d", start, end, len(devices))
60		}
61		now := time.Now()
62		s.lastRun = &now
63		return synced, nil
64	}
65	
66	// LastRun returns when the service last completed a run.
67	func (s *SyncService) LastRun() (time.Time, bool) {
68		if s.lastRun == nil {
69			return time.Time{}, false
70		}
71		return *s.lastRun, true
72	}
73	
74	func (s *SyncService) batchSize() int {
75		if s.batch <= 0 {
76			return 1
77		}
78		return s.batch
79	}
80	
81	// syncOne syncs a single device and reports whether it was in scope.
82	func (s *SyncService) syncOne(d models.Device) (bool, error) {
83		if !s.inRegion(d) {
84			return false, nil
85		}
86		if s.dryRun {
87			log.Printf("sync: would save %s/%s", d.Tenant, d.ID)
88			return true, nil
89		}
90		if err := s.saveWithRetry(d); err != nil {
91			return false, err
92		}
93		return true, nil
94	}
95	
96	// inRegion reports whether the device belongs to the region this service
97	// is responsible for. An unset region means every device.
98	func (s *SyncService) inRegion(d models.Device) bool {
99		region := s.region
100		if region == "" {
101			region = os.Getenv("REGION")
102		}
103		if region == "" {
104			return true
105		}
106		want := "region:" + region
107		for _, t := range d.Tags {
108			if t == want {
109				return true
110			}
111		}
112		return false
113	}
114	
115	func (s *SyncService) saveWithRetry(d models.Device) error {
116		var err error
117		for attempt := 0; attempt <= s.retries; attempt++ {
118			err = s.repo.Save(context.TODO(), d)
119			if err == nil {
120				return nil
121			}
122			time.Sleep(time.Duration(attempt+1) * 100 * time.Millisecond)
123		}
124		_ = s.notifier.Send("ops", "sync failed for "+d.ID)
125		return fmt.Errorf("sync: save %s: %w", d.ID, err)
126	}
