279	// Summarize renders a one-line summary of a device.
280	func (s *DeviceService) Summarize(d models.Device) string {
281		var b strings.Builder
282		b.WriteString(d.Tenant)
283		b.WriteString("/")
284		b.WriteString(d.ID)
285		b.WriteString(" status=")
286		b.WriteString(d.Status)
287		if d.Version != "" {
288			b.WriteString(" version=")
289			b.WriteString(d.Version)
290		}
291		if len(d.Tags) > 0 {
292			b.WriteString(" tags=")
293			b.WriteString(strings.Join(d.Tags, ","))
294		}
295		b.WriteString(" last_seen=")
296		b.WriteString(d.LastSeen.UTC().Format(time.RFC3339))
297		if d.IsOnline() {
298			b.WriteString(" online")
299		}
300		fmt.Fprintf(&b, " uptime=%s", time.Since(s.started).Round(time.Second))
301		return b.String()
302	}
